const { chromium, devices } = require('playwright');
const OUT = process.argv[2];
(async () => { const b = await chromium.launch(); const c = await b.newContext({ ...devices['iPhone 13'] }); const p = await c.newPage(); const errs = []; p.on('pageerror', e => errs.push(e.message));
  let ok = 0, ko = 0; const t = (n, v) => { v ? ok++ : (ko++, console.log('ÉCHEC', n)); };
  await p.goto('http://127.0.0.1:8090/local.html?nouveau'); await p.waitForTimeout(1000);
  await p.evaluate(() => V.avatarPick(() => {}, false)); await p.waitForTimeout(700);
  const q = async (s, shot) => { await p.fill('#sq', s); await p.waitForTimeout(450); if (shot) await p.screenshot({ path: `${OUT}_${shot}.png` }); return p.evaluate(() => [...document.querySelectorAll('[data-sr] b')].map(x => x.textContent.trim())); };
  let r = await q('lunettes or', 'lunettes'); t('lunettes or → aviateur doré + rondes dorées', r.includes('Aviateur doré') && r.includes('Rondes dorées'));
  r = await q('cheveux crépus', 'crepus'); t('cheveux crépus → afro, locks, crépus courts…', ['Afro', 'Crépus courts', 'Locks (dreadlocks)'].every(x => r.includes(x)));
  r = await q('pompier', 'pompier'); t('pompier (homme) → Pompier', r[0] === 'Pompier');
  r = await q('pull rouge', 'pull'); t('pull rouge → Sweat en rouge', r[0] && r[0].startsWith('Sweat') && await p.evaluate(() => !!document.querySelector('[data-sr] .stDot')));
  await p.click('[data-sr="0"]'); await p.waitForTimeout(400); t('appliqué : sweat rouge', await p.evaluate(() => document.querySelector('#big svg').outerHTML.includes('#E35D6A')));
  r = await q('talons'); t('talons → escarpins', r.includes('Escarpins'));
  r = await q('bague orteil'); t('bague orteil', r.includes('Bague d’orteil'));
  r = await q('cheveux roux'); t('cheveux roux → couleur', r.some(x => /roux/i.test(x)));
  r = await q('xyzzz', 'vide'); t('aucun résultat → message', await p.evaluate(() => !!document.querySelector('.stEmpty')));
  await p.click('#sqx'); await p.waitForTimeout(300); t('effacer → retour aux onglets', await p.evaluate(() => !document.querySelector('.stEmpty') && document.querySelector('#bd').children.length > 0));
  await p.click('#tb button[data-t="top"]'); await p.waitForTimeout(200); await p.evaluate(() => { document.querySelector('.studio .stG [data-g="f"]').click(); }); await p.waitForTimeout(400);
  r = await q('pompier'); t('pompier (femme) → Pompière', r[0] === 'Pompière');
  await p.click('[data-sr="0"]'); await p.waitForTimeout(400); t('costume appliqué', await p.evaluate(() => document.querySelector('#big svg').outerHTML.includes('POMPIÈRE')));
  t('aucune erreur', errs.length === 0); if (errs.length) console.log(errs);
  console.log(`recherche : ${ok}/${ok + ko}`); await b.close(); })();
